  INDEX `fk_app_round`(`round_id` ASC) USING BTREE,
  INDEX `fk_app_user`(`user_id` ASC) USING BTREE,
  INDEX `fk_app_slot`(`assigned_slot_id` ASC) USING BTREE,
  CONSTRAINT `fk_app_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_app_round` FOREIGN KEY (`round_id`) REFERENCES `event_rounds` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_app_slot` FOREIGN KEY (`assigned_slot_id`) REFERENCES `slots` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_app_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 128 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

