INSERT INTO `applicants` VALUES (1, 1, 1, NULL, 2, '2026-08-06 08:33:32', 'รชานนท์ คงทอง', '830322922', 'A', 'ข้าวราดแกง', 'ข้าวราดแกง หลากหลาย', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', 'ทดสอบระบบบันทึก', '2026-08-10 12:36:30', 'ได้รับการคัดเลือก', 5, 'paid', '2026-08-20 14:56:06', '', 1, 2568, 'A5', 'ข้าวราดแกง', '2026-08-20 14:48:26', '2026-08-20 14:56:06');
