INSERT INTO `applicants` VALUES (21, 1, 1, NULL, 22, '2026-08-06 08:47:36', 'นางสาวยุพิน อนุมาตย์', '922748680', 'A', 'เครื่องดื่มไม่มีแอลกอฮอล์', 'น้ำลำใยสด', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', '', '2026-08-10 22:23:31', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 1, 2568, 'A1', 'เครื่องดื่มไม่มีแอลกอฮอล์', '2026-08-20 14:48:26', '2026-08-20 14:48:26');
INSERT INTO `applicants` VALUES (22, 1, 1, NULL, 23, '2026-08-06 08:47:54', 'น.ส.จิรนุช ชำนาญ', '809921314', 'A', 'ข้าวไข่เจียว อาหารตามสั่ง', 'ข้าวจี่ ไข่ปิ้งทรงเครื่อง', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ขาดคุณสมบัติ', 'เอกสารครบ แต่ขายไข่ปิ้งไม่ตรงกับข้อกำหนด', '', '2026-08-10 23:12:42', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
INSERT INTO `applicants` VALUES (23, 1, 1, NULL, 24, '2026-08-06 08:51:24', 'นนท์ปวิชญ์ ณรงค์ใย', '968523179', 'C', 'ข้าวไข่เจียว อาหารตามสั่ง', 'เขออ้าย ไข่เจียวเด็กมอขอ : เมนูทานง่าย รสชาติคุ้นเคย แต่เพิ่มคุณค่าและความน่าสนใจด้วยตัวเลือกท็อปปิ้งและซอสหลากหลายรูปแบบ ตอบโจทย์ทุกเพศทุกวัย ไข่เจียวทอดสดใหม่จานต่อจาน คุมความร้อนและเวลาอย่างพิถีพิถัน ทำให้ได้ไข่เจียวที่ไม่อมน้ำมัน เครื่องและท็อปปิ้งจุกๆ เลือกสรรได้ตามใจ: มีวัตถุดิบใส่ไข่เจียวให้เลือกหลากหลาย (เช่น หมูสับ, กุ้ง, ปูอัด, ชะอม, พริกสด, โหระพา, ชีส ฯลฯ) ช่วยให้ลูกค้าสร้างสรรค์เมนูโปรดของตัวเองได้ไม่ซ้ำ มาตรฐานความสะอาดและสุขอนามัย: คำนึงถึงความสะอาดของวัตถุดิบและพื้นที่ปรุงอาหารอย่างเคร่งครัด สร้างความมั่นใจให้ผู้บริโภค เป็นร้านที่อยู่ในกระแสและเป็นที่รู้จักของนักศึกษา มข.', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', '', '2026-08-10 23:16:11', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
INSERT INTO `applicants` VALUES (24, 1, 1, NULL, 26, '2026-08-06 08:56:57', 'นางสาวสมพิศ​ แซ่เล็ก', '832165361', 'C', 'สุกี้โรล/เกี๊ยวต้ม/ชาบู', 'เป็นอาหารปรุงสุกใหม่​ ร้อน​ราคาชิ้นละ10บาท​ ถูกสุขลักษณะ​ เกี๊ยวต้ม​ที่มีหน้ารสชาติให้สามารถเลือกได้​ เหมาะสำหรับทุกเพศ​ ทุกวัย​เข้าถึงได้​', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ไม่ครบถ้วน', '-บัตรประชาชนหมดอายุ\n- ทะเบียนบ้านไม่ชัด', '', '2026-08-10 23:21:18', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
