INSERT INTO `applicants` VALUES (30, 1, 1, NULL, 32, '2026-08-06 09:00:38', 'พิชญา บุตรอำคา', '625641611', 'B', 'ซูชิ/อาหารญี่ปุ่น', 'อาหารญี่ปุ่น สะอาด ปั้นสด ใหม่ทุกวัน', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', '', '2026-08-10 23:15:00', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
