INSERT INTO `applicants` VALUES (72, 1, 1, NULL, 75, '2026-08-07 08:20:51', 'นางสาวศรัญญา ดีพลภักดิ์', '971946326', 'A', 'เครื่องดื่มไม่มีแอลกอฮอล์', 'จุดเด่นของร้าน ร้านของเรามุ่งเน้นการใช้วัตถุดิบคุณภาพจากแหล่งผลิตของตนเองและเกษตรกรในชุมชน โดยเมนูกาแฟใช้เมล็ดกาแฟอาราบิก้า 100% จากสวนที่ปลูกเองในตำบลเทพเสด็จ จังหวัดเชียงใหม่ ส่วนเมนูชาใช้ใบชาออร์แกนิกจากสวนของเรา นำมาผสมและพัฒนาเป็นเมนูเครื่องดื่มที่มีเอกลักษณ์และรสชาติกลมกล่อม ร้านมีความพร้อมในการให้บริการเครื่องดื่มที่หลากหลาย ได้แก่ กาแฟ ชา โกโก้ เครื่องดื่มเนสท์เล่ น้ำผลไม้ และนมสด โดยให้ความสำคัญกับคุณภาพ ความสะอาด และการคัดสรรวัตถุดิบในทุกขั้นตอน เพื่อส่งมอบเครื่องดื่มที่มีมาตรฐานและสร้างความประทับใจแก่ผู้บริโภคทุกกลุ่ม', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', '', '2026-08-10 22:24:12', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
