INSERT INTO `applicants` VALUES (77, 1, 1, NULL, 80, '2026-08-07 11:25:12', 'นัฐพงษ์ จะนารัตน์', '945022482', 'C', 'สื่อเกมการศึกษา/บอร์ดเกม', 'สินค้างานแฮนเมด สร้อยคอ สร้อยข้อมือ สร้อยคอลูกปัด กำไลข้อมือลูกปัด กำไลเชือกเทียน พวงกุญเเจ กิ๊ฟ', 'เป็นผู้จำหน่ายสินค้าด้วยตนเอง', 'ขาดคุณสมบัติ', 'สินค้าไม่ตรงประเภท', '', '2026-08-10 23:16:37', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
