INSERT INTO `applicants` VALUES (79, 1, 1, NULL, 82, '2026-08-07 12:27:15', 'ว่าที่ร.ต.หญิงอรพรรณสิงห์นันท์', '830740599', 'C', 'ยำ', 'ตาดวงยำถาดพ.ศ.2554ยำ35บาท3กล่อง100 ยำอร่อยๆรสเด็ดราคาประหยัดเข้าถึงได้ทุกเพศทุกวัน แม่ค้าน่ารักเป็นกันเองกับลูกค้าทุกๆคนค่ะทางร้านเราให้บริการลูกค้ามาตลอด10ปี สำหรับโปรโมชั่นงานสัปดาห์วิทย์ศาตร์ซื้อ4กล่องแถม1กล่องฟรี1สำหรับทุกๆคนที่มางานค่ะ สด สะอาด ปลอดภัย ใส่ใจทุกเมนูค่ะ', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ไม่ครบถ้วน', 'ไม่มีสำเนาบัตรประจำตัวประชาชน', '', '2026-08-10 23:22:19', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
INSERT INTO `applicants` VALUES (80, 1, 1, NULL, 83, '2026-08-07 13:37:22', 'นพดล ฤกษ์ใหญ่', '935756094', 'B', 'อาหารทอดทานเล่น', 'ไข่หมึกทอด', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', '', '2026-08-10 23:15:27', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
INSERT INTO `applicants` VALUES (81, 1, 1, NULL, 84, '2026-08-07 13:47:09', 'ปิยะธิดา บุระกรณ์', '626565498', 'A', 'ผัดไทย/หอยทอด', 'จำหน่ายสินค้าผัดไทยและหมี่ไก่ฉีก ปัจจุบันมีหน้าร้าน ชื่อร้านผัดไทยไร้เส้น มี 2 สาขา อยู่ที่ตลาดหอ 8 หลังและตลาดมอดินแดงค่ะ ทางร้านขอนำเสนอเป็นเมนูผัดไทยและหมี่ไก่ฉีก โดยเมนูผัดไทย กุ้งตัวโต เนื้อเด้งหวาน ปลาหมึกสด เคี้ยวหนึบกำลังดี ไข่หอม ๆ คลุกเคล้ากับซอสผัดไทยสูตรพิเศษของทางร้าน ถั่วงอกสด กุยช่าย ถั่วลิสงคั่ว และมะนาวสด เพิ่มความกลมกล่อมทุกคำ ครบเครื่อง ครบรส หอม อร่อย แบบต้นตำรับไทยแท้ และหมี่ไก่ฉีก FINDEE ไก่นุ่มฉ่ำ กระเทียมเจียวหอม ซอสสูตรเฉพาะของร้าน (คลุกเคล้าเข้าเส้น หอม อร่อย) ไม่ว่าจะเป็นเมนูเส้นแบบไทย หรือเมนูซิกเนเจอร์ของร้าน เราใส่ใจทุกขั้นตอน เพื่อให้ลูกค้าได้ทานของอร่อย สด ใหม่ ทุกกล่อง ทั้ง 2 เมนู เป็นเมนูที่มีคุณประโยชน์ครบ 5 หมู่ ซื้อพกพาง่าย สะดวก เหมาะสำหรับนักเรียนนักศึกษา ราคาย่อมเยาค่ะ', 'เป็นผู้ที่มีอายุตั้งแต่ 18 ปี ขึ้นไป, เป็นผู้จำหน่ายสินค้าด้วยตนเอง, ไม่เป็นบุคคลที่มีข้อพิพาททางคดีกับมหาวิทยาลัยขอนแก่น และหน่วยงานอื่น ๆ, ไม่เคยกระทำผิดกฎหมาย หรือต้องคำพิพากษาถึงที่สุดว่ากระทำผิดกฎหมาย ยกเว้นการกระทำผิดที่กระทำโดยประมาท หรือความผิดลหุโทษ, ไม่เป็นโรคที่สังคมรังเกียจ หรือโรคติดต่อที่เป็นอันตรายร้ายแรงต่อสังคม และไม่เป็นบุคคลวิกลจริตหรือเป็นบุคคลเสมือนไร้ความสามารถ', 'ครบถ้วน', '', '', '2026-08-10 23:14:06', 'ไม่ได้รับการคัดเลือก', NULL, 'unpaid', NULL, '', 0, NULL, NULL, NULL, '2026-08-20 14:48:26', '2026-08-20 14:48:26');
